import { useDispatch, useSelector } from "react-redux";

import * as XLSX from "xlsx";

import { saveAs } from "file-saver";

import FilterForm from "./FilterForm";

import ResultTable from "./ResultTable";

import { parseDate, formatDate } from "../utils/dateUtils";

import { normalizeText } from "../utils/textUtils";

import toast from "react-hot-toast";

// import {
//   setExcelData,
//   setResults,
//   setStartDate,
//   setEndDate,
//   setEmployeeInput,
// } from "../features/excel/excelSlice";

import {
  selectExcelData,
  selectResults,
  selectStartDate,
  selectEndDate,
  selectEmployeeInput,
} from "../features/excel/excelSelectors";

export default function ExcelFilter({ setCurrentPage }) {
  const dispatch = useDispatch();

  const excelData = useSelector(selectExcelData);

  const results = useSelector(selectResults);

  const startDate = useSelector(selectStartDate);

  const endDate = useSelector(selectEndDate);

  const employeeInput = useSelector(selectEmployeeInput);

  const hasRequiredData =
    startDate && endDate && employeeInput && excelData.length > 0;

  const handleFileUpload = (e) => {
    const file = e.target.files[0];

    if (!file) return;

    // Chỉ cho phép Excel
    const allowedExtensions = [".xlsx", ".xls"];

    const fileName = file.name.toLowerCase();

    const isExcelFile = allowedExtensions.some((ext) => fileName.endsWith(ext));

    if (!isExcelFile) {
      toast.error("Chỉ cho phép file Excel (.xlsx, .xls)");

      e.target.value = "";

      return;
    }

    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const data = evt.target.result;

        const workbook = XLSX.read(data, {
          type: "binary",
        });

        // Lấy sheet đầu tiên (BP.DVKH gửi nội dung Phản ánh)
        const firstSheetName = workbook.SheetNames[0];

        // Lấy sheet thứ 2 BP.QLCL-DV thực hiện Trích xuất
        const secondSheetName = workbook.SheetNames[1];

        const worksheet = workbook.Sheets[firstSheetName];

        const secondWorksheet = workbook.Sheets[secondSheetName];

        if (!worksheet || !secondWorksheet) {
          toast.error("Không đọc được dữ liệu Excel!");

          return;
        }
        /* eslint-disable */console.log(...oo_oo(`3804283715_94_8_94_40_4`,workbook.SheetNames));
        /* eslint-disable */console.log(...oo_oo(`3804283715_95_8_95_45_4`,workbook.secondWorksheet));

        const jsonData = XLSX.utils.sheet_to_json(worksheet, {
          raw: true,
          defval: "",
          range: 1,
        });

        const secondSheetData = XLSX.utils.sheet_to_json(secondWorksheet, {
          raw: true,
          defval: "",
          range: 1,
        });

        if (jsonData.length === 0) {
          toast.error("File Excel không có dữ liệu!");

          return;
        }
        dispatch(setExcelData(jsonData));

        toast.success(`Upload thành công ${jsonData.length} dòng dữ liệu`);
      } catch (error) {
        /* eslint-disable */console.error(...oo_tx(`3804283715_118_8_118_28_11`,error));

        toast.error("File Excel không hợp lệ!");
      }
    };

    reader.readAsBinaryString(file);
  };

  const handleFilter = () => {
    const start = new Date(startDate);

    start.setHours(0, 0, 0, 0);

    const end = new Date(endDate);

    end.setHours(23, 59, 59, 999);

    const employeeArray = employeeInput
      .split(",")
      .map((x) => normalizeText(x))
      .filter(Boolean);

    const filtered = excelData.filter((row) => {
      const employeeKey = Object.keys(row).find((k) =>
        normalizeText(k).includes(normalizeText("Tên nhân viên QLCL-DV")),
      );

      const dateKey = Object.keys(row).find((k) =>
        normalizeText(k).includes(normalizeText("Ngày phản hồi")),
      );

      const contentKey = Object.keys(row).find((k) =>
        normalizeText(k).includes(normalizeText("Nội dung tiếp nhận Phản ánh")),
      );

      if (!employeeKey || !dateKey || !contentKey) return false;

      const excelEmployee = normalizeText(row[employeeKey]);

      const excelDate = parseDate(row[dateKey]);

      if (!excelDate) return false;

      const isEmployeeMatch = employeeArray.some((name) =>
        excelEmployee.includes(name),
      );

      const isDateMatch = excelDate >= start && excelDate <= end;
      /* eslint-disable */console.log(...oo_oo(`3804283715_167_6_171_8_4`,{
        employeeArray,
        excelEmployee,
        excelDate,
      }));
      return isEmployeeMatch && isDateMatch;
    });

    dispatch(setResults(filtered));

    if (filtered.length === 0) {
      toast.error("Không tìm thấy dữ liệu!");

      return;
    }

    toast.success(`Tìm thấy ${filtered.length} kết quả`);
  };

  const handleExportExcel = () => {
    const exportData = results.map((row, index) => ({
      STT: row["STT"],

      "Ngày phản hồi": formatDate(row["Ngày phản hồi"]),

      "Tên nhân viên QLCL-DV": row["Tên nhân viên QLCL-DV"],

      "Nội dung tiếp nhận Phản ánh": row["Nội dung tiếp nhận Phản ánh"],
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);

    const workbook = XLSX.utils.book_new();

    XLSX.utils.book_append_sheet(workbook, worksheet, "KetQua");

    const excelBuffer = XLSX.write(workbook, {
      bookType: "xlsx",
      type: "array",
    });

    const blob = new Blob([excelBuffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8",
    });

    saveAs(blob, `KetQua_${Date.now()}.xlsx`);
    toast.success("Export Excel thành công!");
  };

  return (
    <div className="app-container">
      <div className="app-header">
        <h1>Tra cứu phản ánh</h1>
      </div>

      <FilterForm
        startDate={startDate}
        endDate={endDate}
        employeeInput={employeeInput}
        dispatch={dispatch}
        setStartDate={setStartDate}
        setEndDate={setEndDate}
        setEmployeeInput={setEmployeeInput}
        handleFileUpload={handleFileUpload}
        handleFilter={handleFilter}
        handleExportExcel={handleExportExcel}
        results={results}
        setCurrentPage={setCurrentPage}
        hasRequiredData={hasRequiredData}
      />
      <ResultTable results={results} />
    </div>
  );
